public sealed class PageLoadingView:Grid
{
 private readonly Button _circle=new(){Width=256,Height=256,Padding=new Thickness(0),BorderThickness=new Thickness(0),CornerRadius=new CornerRadius(128),HorizontalContentAlignment=HorizontalAlignment.Center,VerticalContentAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Background=new SolidColorBrush(Microsoft.UI.Colors.Transparent)};
