 private readonly TextBlock _tag=new(){Text="COLETA DE DADOS",FontSize=9,CharacterSpacing=160,HorizontalAlignment=HorizontalAlignment.Center};
 private readonly TextBlock _value=new(){Text="COLETAR",FontSize=22,FontWeight=Microsoft.UI.Text.FontWeights.SemiBold,HorizontalAlignment=HorizontalAlignment.Center};
 private readonly TextBlock _title=new(){FontSize=16,FontWeight=Microsoft.UI.Text.FontWeights.SemiBold,TextAlignment=TextAlignment.Center,TextWrapping=TextWrapping.Wrap,MaxWidth=430};
 private readonly TextBlock _stage=new(){FontSize=12,TextAlignment=TextAlignment.Center,TextWrapping=TextWrapping.Wrap,MaxWidth=430};
