 private readonly Button _cancel=new(){Content="Interromper coleta",Padding=new Thickness(12,6,12,6),FontSize=11};private long _cancelOperation=-1,_shownOperation;
 private readonly Ellipse _ticks=new(){Width=304,Height=304,StrokeThickness=2,StrokeDashArray=new DoubleCollection{1,16},Opacity=.45,IsHitTestVisible=false};
 private readonly Grid _orbital=new(){Width=304,Height=304,IsHitTestVisible=false,RenderTransform=new RotateTransform{CenterX=152,CenterY=152}};
