 public event Action? CancelRequested;public event Action? CollectRequested;public event Action? OptionsRequested;
 public PageLoadingView(){_ring.Children.Add(_track);_ring.Children.Add(_arc);var rotation=new DoubleAnimation{From=0,To=360,Duration=new Duration(TimeSpan.FromSeconds(1.7)),RepeatBehavior=RepeatBehavior.Forever};Storyboard.SetTarget(rotation,_ring.RenderTransform);Storyboard.SetTargetProperty(rotation,"Angle");_ringSpin.Children.Add(rotation);DrawArc(18);var layout=new StackPanel{Spacing=12,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Padding=new Thickness(20)};var zone=new Grid{Width=318,Height=318};zone.Children.Add(_ticks);zone.Children.Add(_halo);_orbital.Children.Add(_satellite);zone.Children.Add(_orbital);var circle=new Grid();circle.Children.Add(_ring);var copy=new StackPanel{Spacing=9,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,IsHitTestVisible=false};copy.Children.Add(_tag);copy.Children.Add(_value);circle.Children.Add(copy);_circle.Content=circle;zone.Children.Add(_circle);layout.Children.Add(zone);layout.Children.Add(_phaseLine);layout.Children.Add(_title);layout.Children.Add(_stage);layout.Children.Add(_hint);_options.HorizontalAlignment=HorizontalAlignment.Center;_cancel.HorizontalAlignment=HorizontalAlignment.Center;layout.Children.Add(_options);layout.Children.Add(_cancel);Children.Add(new ScrollViewer{Content=layout,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden,HorizontalAlignment=HorizontalAlignment.Stretch,VerticalAlignment=VerticalAlignment.Stretch,VerticalContentAlignment=VerticalAlignment.Center});_circle.Click+=(_,_)=>{if(!_busy&&_allowed)CollectRequested?.Invoke();};_options.Click+=(_,_)=>OptionsRequested?.Invoke();_cancel.Click+=(_,_)=>{_cancelOperation=_shownOperation;_cancel.IsEnabled=false;_hint.Text="Solicitando a interrupção da coleta…";CancelRequested?.Invoke();};AutomationProperties.SetName(_circle,"Coletar dados da página");AutomationProperties.SetAutomationId(_circle,"page-data-collect");AutomationProperties.SetLiveSetting(_stage,Microsoft.UI.Xaml.Automation.Peers.AutomationLiveSetting.Polite);
 var pulse=new DoubleAnimation{From=.18,To=.65,Duration=new Duration(TimeSpan.FromSeconds(1.5)),AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever};Storyboard.SetTarget(pulse,_halo);Storyboard.SetTargetProperty(pulse,"Opacity");_pulse.Children.Add(pulse);var spin=new DoubleAnimation{From=0,To=360,Duration=new Duration(TimeSpan.FromSeconds(9)),RepeatBehavior=RepeatBehavior.Forever};Storyboard.SetTarget(spin,_orbital.RenderTransform);Storyboard.SetTargetProperty(spin,"Angle");_pulse.Children.Add(spin);Unloaded+=(_,_)=>{Suspend();};Loaded+=(_,_)=>Animate();}
 public void Paint(LoadingColors c){Background=ThemeService.Brush(c.Surface);_title.Foreground=_value.Foreground=ThemeService.Brush(c.Text);_stage.Foreground=_hint.Foreground=ThemeService.Brush(c.Muted);_tag.Foreground=_arc.Stroke=ThemeService.Brush(c.Accent);_track.Stroke=ThemeService.Brush(c.Track);_halo.Stroke=_ticks.Stroke=_satellite.Fill=ThemeService.Brush(c.Accent);_phaseLine.Foreground=ThemeService.Brush(c.Muted);
 var gradient=new LinearGradientBrush{StartPoint=new Windows.Foundation.Point(0,0),EndPoint=new Windows.Foundation.Point(1,1)};gradient.GradientStops.Add(new GradientStop{Color=((SolidColorBrush)ThemeService.Brush(c.Accent)).Color,Offset=0});gradient.GradientStops.Add(new GradientStop{Color=((SolidColorBrush)ThemeService.Brush(c.Text)).Color,Offset=1});_arc.Stroke=gradient;_options.Foreground=ThemeService.Brush(c.Text);_options.Background=ThemeService.Brush(c.Surface);_options.BorderBrush=ThemeService.Brush(c.Track);_cancel.Foreground=ThemeService.Brush(c.Text);_cancel.Background=ThemeService.Brush(c.Surface);_cancel.BorderBrush=ThemeService.Brush(c.Track);_circle.Foreground=ThemeService.Brush(c.Text);_circle.Resources["ButtonBackgroundPointerOver"]=ThemeService.Brush(c.Surface);_circle.Resources["ButtonBackgroundPressed"]=ThemeService.Brush(c.Surface);_circle.Resources["ButtonBackgroundDisabled"]=ThemeService.Brush(c.Surface);}
 public void Present(string title,DataLoadSnapshot state,bool allowed,bool options,bool canCancel=false){_shownOperation=state.Operation;_busy=state.Phase==DataLoadPhase.Loading;_cancel.Visibility=_busy&&canCancel?Visibility.Visible:Visibility.Collapsed;_cancel.IsEnabled=allowed&&_busy&&_cancelOperation!=state.Operation;_title.Text=title;_stage.Text=state.Stage;_phaseLine.Text=_busy?"COLETA EM ANDAMENTO":state.Phase==DataLoadPhase.Failed?"CONSULTA INTERROMPIDA":"SOLICITAR   ·   COLETAR   ·   EXIBIR";_value.Text=_busy?(state.Percent.HasValue?state.Percent+"%":"…"):state.Phase==DataLoadPhase.Failed?"TENTAR":"COLETAR";_value.FontSize=_busy?48:22;_allowed=allowed;_circle.IsEnabled=allowed;_circle.IsHitTestVisible=allowed&&!_busy;_circle.IsTabStop=allowed&&!_busy;_indeterminate=_busy&&!state.Percent.HasValue;DrawArc(_busy?state.Percent??26:18);_hint.Text=!allowed?"Conecte e autorize o gestor para consultar os dados.":_busy?"Aguarde a conclusão da consulta. Você pode navegar para outra área.":state.Phase==DataLoadPhase.Failed?"Clique no círculo para tentar novamente.":"Clique no círculo para iniciar a coleta desta área.";_options.Visibility=options&&!_busy?Visibility.Visible:Visibility.Collapsed;_options.IsEnabled=allowed&&!_busy;AutomationProperties.SetName(_circle,_busy?"Coleta em andamento":state.Phase==DataLoadPhase.Failed?"Tentar coletar novamente":"Coletar dados de "+title);Animate();}
 private void DrawArc(double percent){var geometry=new PathGeometry();var figure=new PathFigure{StartPoint=new Windows.Foundation.Point(125,8),IsClosed=false};var p=Math.Clamp(percent,0,100);if(p>=100){figure.Segments.Add(new ArcSegment{Point=new Windows.Foundation.Point(125,242),Size=new Windows.Foundation.Size(117,117),IsLargeArc=false,SweepDirection=SweepDirection.Clockwise});figure.Segments.Add(new ArcSegment{Point=new Windows.Foundation.Point(125,8),Size=new Windows.Foundation.Size(117,117),IsLargeArc=false,SweepDirection=SweepDirection.Clockwise});}else if(p>0){var angle=2*Math.PI*p/100;figure.Segments.Add(new ArcSegment{Point=new Windows.Foundation.Point(125+117*Math.Sin(angle),125-117*Math.Cos(angle)),Size=new Windows.Foundation.Size(117,117),IsLargeArc=p>50,SweepDirection=SweepDirection.Clockwise});}geometry.Figures.Add(figure);_arc.Data=geometry;}
 public void Suspend(){_pulse.Stop();_ringSpin.Stop();_animating=false;}
 private void Animate(){if(!_busy||!IsLoaded){_pulse.Stop();_ringSpin.Stop();_animating=false;return;}if(!_indeterminate)_ringSpin.Stop();if(_animating){if(_indeterminate)_ringSpin.Begin();return;}try{if(new Windows.UI.ViewManagement.UISettings().AnimationsEnabled){_pulse.Begin();if(_indeterminate)_ringSpin.Begin();_animating=true;}}catch(InvalidOperationException){}}
